message.content:
{
  "appearance_facts": [
    {
      "location": "chart center, vertical bar chart",
      "fact": "Five vertical bars left-to-right: Solar (yellow), Wind (light blue), Hydroelectric (medium blue), Biomass (green), Geothermal (brown). Wind bar is tallest, reaching near the 70 tick; Solar bar is second tallest near 40; Hydroelectric near 50; Biomass and Geothermal are shorter, near 20-35."
    },
    {
      "location": "above each bar, top of plot",
      "fact": "Bold percentage labels sit directly above each bar: 41.2% above Solar, 29.8% above Wind, 18.5% above Hydroelectric, 7.2% above Biomass, 3.3% above Geothermal."
    },
    {
      "location": "left axis and bottom axis",
      "fact": "Y-axis runs 0 to 70 in steps of 5; x-axis lists the five source names aligned under each bar."
    }
  ],
  "printed_facts": [
    {
      "location": "chart title, top center",
      "fact": "Title reads 'Renewable Energy Production by Source'."
    },
    {
      "location": "y-axis label, upper left",
      "fact": "Axis label reads 'Reported production share (%)'."
    },
    {
      "location": "bar value annotations",
      "fact": "Solar = 41.2%; Wind = 29.8%; Hydroelectric = 18.5%; Biomass = 7.2%; Geothermal = 3.3%."
    },
    {
      "location": "x-axis category labels",
      "fact": "Categories in order: Solar, Wind, Hydroelectric, Biomass, Geothermal."
    }
  ],
  "public_definitions": [
    "User goal: 'Review the renewable generation mix dashboard, identify the largest renewable generation contribution source, then route that source record to escalated contribution review.'",
    "Routing criterion (readonly): 'Largest renewable generation contribution source'",
    "Record workflow (readonly): 'Escalated contribution review'",
    "Option labels: 'Escalate Solar to contribution review', 'Escalate Wind to contribution review', 'Keep Hydroelectric in routine source monitoring'"
  ],
  "uncertain": [
    "The bar heights and the printed percentage labels are visually inconsistent (e.g., the Wind bar is drawn tallest yet labeled 29.8%, while the Solar bar is shorter yet labeled 41.2%); the intended 'largest contribution source' is therefore ambiguous between reading the printed values (Solar, 41.2%) and reading the bar heights (Wind).",
    "Whether the y-axis 'Reported production share (%)' values are meant to sum to 100% is not stated; the printed labels sum to 99.8%."
  ]
}
